const RAW_DIGIMON_DATA: readonly RawDigimonRecord[] = RAW_PART_1.concat(RAW_PART_2, RAW_PART_3, RAW_PART_4)

export const DIGIMON_DATA: readonly DigimonRecord[] = RAW_DIGIMON_DATA.map((record) => ({
  name_en: record.name_en,
  name_jp: record.name_jp,
  next_evolutions: record.next_evolutions as readonly DigimonId[],
  stage: record.stage,
  sprite: record.sprite,
  id: record.id as DigimonId,
  url: record.url,
}))

